app/app.css:
* { box-sizing: border-box; }
body { margin:0; background:#edf2f7; color:#20334a; font:16px/1.5 Arial,sans-serif; }
main { max-width:900px; margin:auto; padding:20px; }
h1 { font-size:26px; } h2 { font-size:21px; } h3 { font-size:18px; margin:0 0 12px; }
button,textarea { font:inherit; color:inherit; }
button { background:white; border:1px solid #8094ac; border-radius:4px; min-height:38px; padding:7px 12px; cursor:pointer; }
button:focus-visible,textarea:focus-visible,summary:focus-visible { outline:3px solid #1859a6; outline-offset:2px; }
summary { cursor:pointer; padding:6px 0; }
label { display:block; margin:10px 0 4px; }
textarea { width:100%; border:1px solid #8094ac; padding:8px; resize:vertical; }
#days { display:flex; gap:8px; overflow:hidden; padding:5px; }
#days button { flex:0 0 auto; white-space:nowrap; }
#days [aria-selected="true"] { background:#1859a6; color:white; }
.session { margin:16px 0; padding:16px; border:1px solid #bccbdc; border-radius:5px; background:white; }
.location { white-space:nowrap; overflow:hidden; height:24px; }
.description { white-space:normal; }
#load-error { color:#8a251a; min-height:24px; }

#days { overflow:auto; }
.location { white-space:normal; overflow:visible; height:auto; overflow-wrap:anywhere; }
.description { white-space:pre-wrap; }

